// Shared page rendering, navigation, and view composition.

async function loadLibraryPage(reset=true,keepFocus=false){const requestId=++libraryRequestId;const offset=reset?0:(libraryPage.items||[]).length;try{const result=await api(libraryUrl(offset));if(requestId!==libraryRequestId)return;if(reset)libraryPage=result;else libraryPage={...result,items:[...(libraryPage.items||[]),...(result.items||[])]};if(activeView==='library'){const selection=keepFocus?$('#library-filter')?.selectionStart:null;renderView();if(keepFocus){const input=$('#library-filter');input?.focus();if(selection!=null)input?.setSelectionRange(selection,selection);}}}catch(err){toast(err.message,'error');}}
async function loadStudyItems(reset=true,keepFocus=false){const requestId=++studyRequestId,offset=reset?0:studyPage.items.length,params=new URLSearchParams({limit:String(studyPage.limit),offset:String(offset),q:studyQuery,mastery:studyMastery,type:studyType,paper_id:studyPaperId,due:studyDueOnly?'1':'0'}),selection=keepFocus?$('#study-filter')?.selectionStart:null;try{const result=await api(`/api/study-items?${params}`);if(requestId!==studyRequestId)return;studyPage=reset?result:{...result,items:[...studyPage.items,...result.items]};if(activeView==='prereading'){renderView();if(keepFocus){const input=$('#study-filter');input?.focus();if(selection!=null)input?.setSelectionRange(selection,selection);}}}catch(err){toast(`读前知识加载失败：${err.message}`,'error');}}
function renderSidebar(){
  $('#nav-library-count').textContent=appState?.total||0;
  $$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===activeView));
  if(['prereading','agents','analytics'].includes(activeView))$('#nav-more').open=true;
  $('#crumb-current').textContent=PAGE_NAMES[activeView]||'今日';
  const active=queries.filter(q=>q.active);
  $('#sidebar-topics').innerHTML=active.length?active.slice(0,6).map((q,i)=>`<button class="topic-chip" data-query-run="${q.id}"><span class="topic-bullet" style="background:${['#709477','#c29a64','#6f91a2','#b27c69','#8c82a2','#7d9b94'][i%6]}"></span><span>${esc(q.name)}</span><span class="topic-count">${q.cadence_hours>=168?'周':'日'}</span></button>`).join(''):`<div class="topic-empty">保存一个主题检索<br>自动追踪新论文</div>`;
}
function syncViewUrl(view,mode='push'){
 const url=new URL(location.href);
 if(view==='home')url.searchParams.delete('view');else url.searchParams.set('view',view);
 const next=`${url.pathname}${url.search}${url.hash}`;
 const current=`${location.pathname}${location.search}${location.hash}`;
 if(next!==current)history[mode==='replace'?'replaceState':'pushState']({...history.state,litloomView:view},'',next);
}
function setView(view,historyMode='push'){
 activeView=PAGE_NAMES[view]?view:'home';
 if(historyMode!=='none')syncViewUrl(activeView,historyMode);
 persistUiState();
 $$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===activeView));
 if(['prereading','agents','analytics'].includes(activeView))$('#nav-more').open=true;
 $('#crumb-current').textContent=PAGE_NAMES[activeView]||'今日';
 renderView();
 if(activeView==='library')loadLibraryPage(true);
 if(activeView==='prereading')loadStudyItems(true);
 if(activeView==='deepread')loadDeepReadWorkspace(deepReadPaperId||selectedPaperId);
 if(activeView==='agents')loadAgentWorkspace();
 if(activeView==='discover')loadDiscoveryHistory();
 window.scrollTo({top:0,behavior:'smooth'});
}
syncViewUrl(activeView,'replace');
window.addEventListener('popstate',()=>setView(new URLSearchParams(location.search).get('view')||'home','none'));
function viewHead(kicker,title,subtitle,actions=''){return `<div class="view-head"><div><div class="eyebrow">${kicker}</div><h1 class="view-title">${title}</h1><p class="view-subtitle">${subtitle}</p></div><div class="head-actions">${actions}</div></div>`;}
function countStatus(s){return (appState?.counts?.[s]||0);}
function statusPill(s){return `<span class="status-pill status-${s||'inbox'}">${STATUS[s]||STATUS.inbox}</span>`;}
const READING_CARD_FIELDS = {research_question:'研究问题',contribution:'核心贡献',method:'方法与模型',datasets:'数据集 / 数据来源',baselines:'基线与对照',results:'关键结果',limitations:'局限与风险',reproducibility:'可复现性',evidence_notes:'证据定位与核验',relevance_to_me:'对我的课题启发',next_steps:'下一步行动'};
function readingCardFields(card={}){return Object.entries(READING_CARD_FIELDS).map(([key,label])=>`<div class="form-field"><label>${label}</label><textarea class="field-area reading-card-field" data-reading-field="${key}" placeholder="记录可回到原文核验的事实…">${esc(card[key]||'')}</textarea></div>`).join('');}
function paperRow(p, compact=false){
 const meta=[p.year,p.venue,p.doi?'DOI':''].filter(Boolean).map(esc);
 const source=(p.sources||[])[0]?.source;
 return `<article class="paper-row" data-open-paper="${p.id}"><div class="paper-main"><div class="paper-meta">${meta.map((m,i)=>`${i?'<i class="meta-dot"></i>':''}<span>${m}</span>`).join('')}${source?`<span class="source-pill">${esc(SOURCE_NAME[source]||source)}</span>`:''}</div><div class="paper-title">${esc(p.title)}</div><div class="paper-authors">${esc(p.authors||'作者信息待补充')}</div></div><div>${compact?'':statusPill(p.status)}</div></article>`;
}
function emptyState(title,body,action=''){return `<div class="empty-state"><div class="empty-mark">⌕</div><b>${title}</b>${body}${action?`<div style="margin-top:13px">${action}</div>`:''}</div>`;}
function latestRun(){return runs[0]||null;}
function runResultSummary(run){const newCount=Number(run?.new_count||0),duplicateCount=Number(run?.duplicate_count||0);if(run?.candidate_mode){const candidates=Number(run.candidate_count||0),imported=Number(run.imported_count||0),pending=Number(run.awaiting_review_count??Math.max(0,candidates-imported));return `${candidates} 个候选 · ${pending} 待确认${imported?` · ${imported} 已入库`:''}`;}if(typeof run?.candidate_mode!=='boolean'&&!newCount&&!duplicateCount)return '结果计数暂不可用';return `${newCount} 新 · ${duplicateCount} 重复`;}
function evaluationPanel(evaluation={}){
 const pct=value=>value==null?'—':`${Math.round(Number(value)*100)}%`;
 const status=evaluation.status==='ready'?'可用于比较版本':'样本不足，继续标记相关/忽略';
 return `<section class="surface-card evaluation-panel"><div class="section-heading" style="margin:0 0 10px"><div><h3>检索质量评测</h3><p>只使用你的明确反馈，作为评分和来源策略的可复现实验基线</p></div><span class="evaluation-status">${status}</span></div><div class="evaluation-grid"><div><small>Precision@5</small><b>${pct(evaluation.precision_at_5)}</b></div><div><small>Precision@10</small><b>${pct(evaluation.precision_at_10)}</b></div><div><small>已标注样本</small><b>${evaluation.judged_matches||0}</b></div><div><small>相关比例</small><b>${pct(evaluation.judged_precision)}</b></div></div><div class="evaluation-note">当前只统计“标记相关”和“忽略”样本；改动检索词、排序或来源后，可用同一批反馈比较前后变化。</div></section>`;
}
function globalAiJobsPanel(){
  const ai=(aiJobs||[]).map(job=>({...job,kind:'ai',updated_at:job.updated_at||job.created_at}));
  const sync=(syncJobs||[]).map(job=>({...job,kind:'sync',updated_at:job.updated_at||job.created_at}));
  const jobs=[...ai,...sync].filter(job=>['queued','running'].includes(job.status)).sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at))).slice(0,5);
  if(!jobs.length)return '';
  const active=jobs;
  const rows=jobs.map(job=>{
    if(job.kind==='sync'){
      const status=job.status==='success'?'已完成':job.status==='running'?'运行中':job.status==='interrupted'?'上次运行中断':job.status==='retryable'?'等待重试':job.status==='partial'?'部分完成':job.status==='failed'?'失败':job.status;
      const sources=Array.isArray(job.sources)?job.sources:(()=>{try{return JSON.parse(job.sources_json||'[]')}catch{return []}})();
      const sourceIndex=Math.max(0,sources.indexOf(String(job.stage||'').replace(/^source:/,'')));
      const stage=discoveryStageLabel(job.stage);
      const detail=job.error||job.last_error||job.run_error||'';
      return `<div class="source-line" style="align-items:flex-start;gap:12px"><span><b>文献检索 · ${esc(status)}</b><small style="display:block;color:#9aa59d;margin-top:3px">${esc(job.query_name||job.query||'研究主题')} · ${esc(stage)}${detail?` · ${esc(detail)}`:''}</small></span><span style="white-space:nowrap">${job.run_started_at?esc(timeAgo(job.run_started_at)):''}${['success','partial','failed'].includes(job.status)?` · ${esc(runResultSummary(job,true))}`:''}</span></div>`;
    }
    const total=Number(job.progress_total||0),current=Math.min(total,Number(job.progress_current||0)),pct=total?Math.round(current/total*100):job.status==='success'?100:0;
    return `<div class="source-line" style="align-items:flex-start;gap:12px"><span><b>${esc(aiJobLabel(job))} · ${esc(aiJobStatusText(job))}</b><small style="display:block;color:#9aa59d;margin-top:3px">${esc(job.paper_title||job.paper_id)} · ${esc(job.message||'')}${job.error?` · ${esc(job.error)}`:''}</small>${total&&['queued','running'].includes(job.status)?`<i class="ai-job-progress" style="display:block;margin-top:6px;width:180px"><i style="width:${pct}%"></i></i>`:''}</span><span style="white-space:nowrap">${total?`${current}/${total} · ${pct}%`:''}${job.duration_ms?` · ${Math.round(Number(job.duration_ms)/1000)} 秒`:''}</span></div>`;
  }).join('');
  return `<section class="surface-card decision-card ai-global-jobs"><div class="section-heading" style="margin:0 0 10px"><div><h3>正在运行</h3><p>切换页面或刷新不会停止任务；完成结果会保存在论文记录和任务中心。</p></div><span class="evaluation-status">${active.length} 个任务</span></div>${rows}<div style="margin-top:9px"><button class="text-link" data-nav="settings">打开任务中心 →</button></div></section>`;
}
function renderGlobalTaskStatus(){
  const target=$('#global-task-status');
  if(!target)return;
  const ai=(aiJobs||[]).map(job=>({...job,kind:'ai',updated_at:job.updated_at||job.created_at}));
  const sync=(syncJobs||[]).map(job=>({...job,kind:'sync',updated_at:job.updated_at||job.created_at}));
  const metadata=['queued','running','partial','failed','interrupted'].includes(metadataDraftJob?.status)?[{...metadataDraftJob,kind:'metadata',updated_at:metadataDraftJob.updated_at||metadataDraftJob.created_at}]:[];
  const all=[...ai,...sync,...metadata].sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||'')));
  // Keep the run currently shown in Discovery at the front even when an AI
  // job received a newer heartbeat, so the global banner describes the page
  // the user is actually watching.
  if(activeDiscoveryRunId){const currentIndex=all.findIndex(job=>job.kind==='sync'&&(job.run_id===activeDiscoveryRunId||job.id===activeDiscoveryRunId));if(currentIndex>0)all.unshift(all.splice(currentIndex,1)[0]);}
  const active=all.filter(job=>['queued','running'].includes(job.status));
  if(!active.length){target.innerHTML='';target.classList.remove('visible');return;}
  const recent=active.slice(0,2);
  const label=`后台任务 · ${active.length} 个运行中`;
  const detail=recent.map(job=>{
    const seconds=Math.floor(Number(job.duration_ms||0)/1000);
    const elapsed=seconds?` · ${seconds<60?`${seconds} 秒`:`${Math.floor(seconds/60)} 分钟`}`:'';
    if(job.kind==='metadata'){
      const status=({queued:'排队中',running:'运行中',partial:'部分完成',failed:'失败',interrupted:'上次运行中断'})[job.status]||job.status;
      return `元数据识别：${status} · ${job.message||''}${job.error?` · ${job.error}`:''}`;
    }
    if(job.kind==='sync'){
      const source=job.current_source?` · ${SOURCE_NAME[job.current_source]||job.current_source}`:'';
      const progress=job.source_total?` · 来源 ${job.source_index}/${job.source_total}`:'';
      const status=({queued:'排队中',running:'运行中',success:'已完成',partial:'部分完成',failed:'失败',interrupted:'上次运行中断',retryable:'等待重试',cancelled:'已取消'})[job.status]||job.status;
      const stage=job.stage==='planning'?'正在规划检索':job.stage==='semantic_planning'?'正在理解研究问题并扩展术语':job.stage==='model_web_search'||job.stage?.startsWith('model_web_search:')?'正在调用 AI 检索工具':job.stage==='completed'?'检索完成':job.stage?.startsWith('source:')?'正在检索':'';
      const problem=job.error||job.last_error||job.run_error||'';
      return `文献检索：${job.query_name||job.query||'研究主题'} · ${status}${stage?` · ${stage}`:''}${progress}${source}${elapsed}${problem?` · ${problem}`:''}`;
    }
    const total=Number(job.progress_total||0),current=Math.min(total,Number(job.progress_current||0));
    const progress=total?` ${current}/${total} · ${Math.round(current/total*100)}%`:'';
    const problem=job.error?` · ${job.error}`:'';
    return `${aiJobLabel(job)}：${job.paper_title||job.paper_id} · ${aiJobStatusText(job)}${progress}${elapsed}${job.message?` · ${job.message}`:''}${problem}`;
  }).join('；');
  target.classList.add('visible');
  target.innerHTML=`<div class="global-task-status-inner"><span class="global-task-status-label">${esc(label)}</span><span class="global-task-status-detail">${esc(detail)}</span><button class="text-link" data-nav="settings">任务中心 →</button></div>`;
}
const renderGlobalTaskStatusWithoutPdf=renderGlobalTaskStatus;
renderGlobalTaskStatus=function(){
 renderGlobalTaskStatusWithoutPdf();
 const active=(pdfIngestJobs||[]).filter(job=>['queued','running'].includes(job.status));if(!active.length)return;
 const target=$('#global-task-status');if(!target)return;
 const detail=active.slice(0,2).map(job=>`PDF 导入：${Number(job.completed||0)+Number(job.failed||0)}/${Number(job.total||0)} 已处理 · ${Number(job.failed||0)} 失败 · ${job.stage==='queued'?'排队中':'并发解析中'}`).join('；');
 if(!target.classList.contains('visible'))target.innerHTML='<div class="global-task-status-inner"><span class="global-task-status-label">PDF 后台任务</span><span class="global-task-status-detail"></span><button class="text-link" data-action="pdf-import">查看任务 →</button></div>';
 else {const label=$('.global-task-status-label',target);if(label)label.textContent='后台任务';const button=$('.global-task-status-inner .text-link',target);if(button){button.dataset.action='pdf-import';button.textContent='PDF 任务 →';}}
 target.classList.add('visible');const info=$('.global-task-status-detail',target);if(info)info.textContent+=(info.textContent?'；':'')+detail;
};

const AGENT_STATUS_TEXT={draft:'草稿',awaiting_confirmation:'等待计划确认',queued:'排队中',running:'运行中',paused:'已暂停',interrupted:'服务重启中断',success:'已完成',partial:'部分完成',failed:'失败',cancelled:'已取消',active:'进行中',completed:'已完成',archived:'已归档'};
const AGENT_STEP_TEXT={queued:'等待执行',running:'执行中',success:'已完成',failed:'失败',skipped:'已跳过',cancelled:'已取消',awaiting_confirmation:'等待确认'};
function agentElapsedText(seconds){const value=Math.max(0,Number(seconds)||0);if(value<60)return `${Math.round(value)} 秒`;const minutes=Math.floor(value/60),rest=Math.round(value%60);return `${minutes} 分 ${rest} 秒`;}
function agentGoalForm(){return `<section class="surface-card agent-goal-form-card"><div class="section-heading"><div><h3>新建研究目标</h3><p>描述研究任务，选择自主 Agent 或可复现的专项流程。</p></div></div><form id="agent-goal-form"><div class="form-grid"><div class="form-field"><label>运行模式</label><select class="field-select" name="workflow"><option value="autonomous" selected>自主 Agent（模型按结果动态选工具）</option><option value="auto">按目标自动选择专项流程</option><option value="research_map">梳理研究方向</option><option value="evidence_review">精读与证据核验</option><option value="follow_up">追踪前沿变化</option></select></div><div class="form-field full"><label>你希望 Agent 完成什么？ *</label><textarea class="field-area" name="objective" required minlength="8" placeholder="例如：梳理食物体积估计方法，先检查已有论文，再补找近期工作并比较数据集与指标。"></textarea></div><div class="form-field full agent-schedule-option"><label class="check-label"><input type="checkbox" name="auto_run"> 定期自动追踪新增论文</label><select class="field-select" name="cadence_hours" aria-label="自动追踪频率"><option value="24">每天</option><option value="168" selected>每周</option><option value="720">每月</option></select><span class="form-help">定期运行仅用于前沿追踪；新论文仍进入候选列表，不会自动入库。</span></div><details class="form-field full agent-advanced-options"><summary>检索范围与结果格式（可选）</summary><div class="agent-advanced-fields"><div class="form-field"><label>目标名称</label><input class="field-input" name="name" maxlength="240" placeholder="留空时从任务描述生成"></div><div class="form-field"><label>核心检索问题</label><input class="field-input" name="core_question" placeholder="留空时使用任务描述"></div><div class="form-field"><label>关注方法、数据集或指标</label><input class="field-input" name="focus" placeholder="方法, 数据集, 指标"></div><div class="form-field"><label>排除条件</label><input class="field-input" name="exclusions" placeholder="非同行评审, 不相关任务"></div><div class="form-field"><label>时间起点</label><input class="field-input" name="year_from" type="number" min="1800" max="2200" placeholder="例如 2022"></div><div class="form-field"><label>时间终点</label><input class="field-input" name="year_to" type="number" min="1800" max="2200" placeholder="默认至今"></div><div class="form-field full"><label>期望产物</label><input class="field-input" name="deliverables" value="研究地图, 阅读路线, 论文比较表"></div><div class="form-field full"><label>检索来源</label><div class="agent-source-options"><label class="check-label"><input type="checkbox" name="source" value="arxiv" checked> arXiv</label><label class="check-label"><input type="checkbox" name="source" value="openalex" checked> OpenAlex</label><label class="check-label"><input type="checkbox" name="source" value="crossref" checked> Crossref</label><label class="check-label"><input type="checkbox" name="source" value="europepmc"> Europe PMC</label><label class="check-label"><input type="checkbox" name="source" value="semanticscholar"> Semantic Scholar</label><label class="check-label"><input type="checkbox" name="source" value="dblp"> DBLP</label><label class="check-label"><input type="checkbox" name="source" value="openreview"> OpenReview</label></div></div></div></details></div><div class="agent-form-actions"><button class="button primary" type="submit">生成并审阅 Agent 计划</button><span>Agent 依据证据选择工具；候选入库、外部下载和全文发送仍需确认。</span></div></form></section>`;}
function agentStepOutcome(step){const output=step?.output;if(!output||typeof output!=='object')return '';const labels={papers:'论文',candidates:'候选',claims:'研究主张',critiques:'批判点',rows:'比较项',route:'阅读步骤',results:'核验项',new_papers:'新增',changed_papers:'版本变化',repeated_papers:'重复命中',gaps:'待补缺口',paper_overviews:'专业分析'};const counts=Object.entries(labels).filter(([key])=>Array.isArray(output[key])).map(([key,label])=>`${label} ${output[key].length}`);if(output.coverage?.candidate_count!=null)counts.unshift(`覆盖 ${output.coverage.candidate_count} 篇`);if(output.evidence_count!=null)counts.push(`证据 ${output.evidence_count} 条`);if(output.fulltext_count!=null)counts.push(`全文 ${output.fulltext_count} 篇`);if(output.abstract_only_count!=null)counts.push(`仅摘要 ${output.abstract_only_count} 篇`);if(output.new_count!=null)counts.push(`新增 ${output.new_count} 篇`);if(output.resolved_count!=null)counts.push(`补证 ${output.resolved_count} 项`);if(output.stop_reason)counts.push(output.stop_reason);if(output.reason)counts.push(output.reason);return counts.length?`结果：${esc(counts.join(' · '))}`:'';}
function agentStepRows(run){return (run?.steps||[]).map(step=>`<div class="agent-step"><span class="agent-step-state ${esc(step.status)}">${esc(AGENT_STEP_TEXT[step.status]||step.status)}</span><div class="agent-step-body"><b>${esc(step.title)}</b><small>${esc(step.agent_type)} · ${esc(step.tool_name)} · ${esc(step.tool_class)}${step.message?` · ${esc(step.message)}`:''}${step.error?` · ${esc(step.error)}`:''}</small>${agentStepOutcome(step)?`<small class="agent-step-outcome">${agentStepOutcome(step)}</small>`:''}${step.completion?.required?.length?`<small class="agent-step-contract">完成条件：${esc(step.completion.required.join('、'))}</small>`:''}${step.progress_total?`<div class="ai-job-progress"><i style="width:${Math.round(Math.min(step.progress_total,step.progress_current||0)/step.progress_total*100)}%"></i></div>`:''}</div><span class="agent-step-attempt">${Number(step.attempts||0)?`尝试 ${step.attempts}`:''}</span></div>`).join('')||'<div class="agent-empty-inline">计划确认后，执行步骤会显示在这里。</div>';}
 function agentCandidateMarkup(run){const searchStep=(run?.steps||[]).find(step=>step.step_key==='search_candidates');const triage=(run?.steps||[]).find(step=>step.step_key==='triage_candidates');const citation=(run?.steps||[]).find(step=>step.step_key==='expand_citations');const prepare=(run?.steps||[]).find(step=>step.step_key==='prepare_fulltext');const preparedById=new Map((prepare?.output?.papers||[]).map(item=>[item.paper_id,item]));const base=triage?.output?.candidates||searchStep?.output?.papers||[];const citationPapers=citation?.output?.papers||[];const byIdentity=new Map();[...base,...citationPapers].forEach(p=>{const key=p.doi||p.arxiv_id||p.title||p.id;if(key&&!byIdentity.has(key))byIdentity.set(key,p);});const papers=[...byIdentity.values()].map(p=>({...p,...(preparedById.get(p.local_paper_id)||{})}));if(!papers.length)return '<div class="agent-empty-inline">检索完成后，候选论文会显示在这里；目前不会自动入库。</div>';const canImport=papers.some(p=>p.id?.startsWith('candidate:'));const canDownload=papers.some(p=>p.local_paper_id&&p.download_urls?.length);return `<div class="agent-candidate-toolbar"><span>候选 ${papers.length} 篇 · 勾选后才会加入文献库${citationPapers.length?` · 引用扩展 ${citationPapers.length} 篇`:''}</span><button class="button small primary" data-agent-import ${canImport?'':'disabled'}>加入选中候选</button>${canDownload?'<button class="button small" data-agent-download>下载选中 PDF</button>':''}</div><div class="agent-candidate-list">${papers.map(p=>`<label class="agent-candidate"><input type="checkbox" data-agent-candidate="${esc(p.id||'')}" data-agent-local="${esc(p.local_paper_id||'')}"><span class="agent-candidate-main"><b>${esc(p.title||'无标题')}</b><small>${esc([p.year,p.venue,p.relation?`引用关系 · ${p.relation}`:'',p.relevance_label,p.discovery_only?'网页线索 · 未核验':(p.verification_status==='verified'?'已学术核验':''),p.has_local_pdf?'本机有 PDF':'',p.state==='downloadable'?'有公开 PDF 可下载':'',p.focus_reason].filter(Boolean).join(' · '))}</small><span>${esc((p.abstract||'').slice(0,260))}${(p.abstract||'').length>260?'…':''}</span></span><span class="agent-candidate-score">${esc(p.discovery_score??p.relevance_score??'—')}</span></label>`).join('')}</div>`;}
 function agentPaperOverviewMarkup(data){const list=Array.isArray(data?.paper_overviews)?data.paper_overviews:[];if(!list.length)return '';const fieldLabels={problem:'研究问题',method:'方法结构',assumptions:'关键假设',data_and_experiments:'数据与实验',results:'结果证据',limitations:'局限与边界'};const refMarkup=refs=>(Array.isArray(refs)?refs:[]).slice(0,3).map(ref=>`<span class="agent-evidence-ref">${ref.page!=null?`第 ${esc(ref.page)} 页`:'摘要'} · ${esc(ref.section||'来源')} · ${esc(ref.quote||'')}</span>`).join('');return `<div class="agent-paper-overview"><div class="agent-paper-overview-head"><div><b>专业论文分析总览</b><small>逐篇输出研究问题、方法、实验、风险和下一步；每个正向判断都保留来源范围。</small></div><span class="evaluation-status">全文 ${Number(data.fulltext_count||0)} · 摘要级 ${Number(data.abstract_only_count||0)} · 证据 ${Number(data.evidence_count||0)}</span></div>${list.map(item=>{const coverage=item.evidence_coverage||{};const analysis=item.analysis||{};const risks=item.critical_risks||[];const actions=item.next_actions||[];const repro=item.reproducibility||[];const visual=item.visual_inventory||[];const missing=coverage.missing_sections||[];return `<article class="agent-paper-overview-card"><div class="agent-paper-overview-title"><b>${esc(item.title||'未命名论文')}</b><span>${esc(item.source_scope||'unverified')} · 覆盖 ${Number(coverage.coverage_percent||0)}%</span></div><div class="agent-paper-analysis-grid">${Object.entries(fieldLabels).map(([key,label])=>{const value=analysis[key]||{};return `<div class="agent-paper-analysis-field"><b>${label}</b><p>${esc(value.text||'未定位')}</p>${refMarkup(value.evidence_refs)}</div>`;}).join('')}</div>${missing.length?`<div class="agent-paper-gap"><b>尚未覆盖的章节</b><span>${missing.map(value=>esc(value)).join(' · ')}</span></div>`:''}${visual.length?`<details class="agent-paper-visual"><summary>视觉对象线索 · ${visual.length}</summary>${visual.slice(0,8).map(value=>`<div><b>第 ${esc(value.page||'')} 页</b><span>${esc(value.kind||'图表/公式')}</span><small>${esc(value.reason||'')}</small></div>`).join('')}</details>`:''}${risks.length?`<div class="agent-paper-risk"><b>批判与风险</b>${risks.slice(0,5).map(risk=>`<p><span>${esc(risk.severity||'medium')}</span> ${esc(risk.text||'')}</p>`).join('')}</div>`:''}<details class="agent-paper-repro"><summary>复现核对清单 · ${repro.filter(value=>value.status==='evidence_found').length}/${repro.length} 已定位</summary>${repro.slice(0,8).map(value=>`<div><b>${esc(value.item)}</b><span>${esc(value.status==='evidence_found'?'已定位':'未定位')}</span>${refMarkup(value.evidence_refs)}<small>${esc(value.next_step||'')}</small></div>`).join('')}</details>${actions.length?`<div class="agent-paper-actions"><b>下一步</b>${actions.slice(0,5).map(action=>`<span>${esc(action.priority||'')} · ${esc(action.action||'')} · ${esc(action.why||'')}</span>`).join('')}</div>`:''}${(item.open_questions||[]).length?`<details class="agent-paper-questions"><summary>未解决问题 · ${item.open_questions.length}</summary><ul>${item.open_questions.slice(0,8).map(value=>`<li>${esc(value)}</li>`).join('')}</ul></details>`:''}</article>`;}).join('')}</div>`;}
 function agentArtifactMarkup(run){const artifacts=Array.isArray(run?.artifacts)?run.artifacts:[];const preferred=['research_map','evidence_brief','follow_up_digest'];const artifact=artifacts.find(item=>preferred.includes(item?.artifact_type))||artifacts[0];if(!artifact)return '';const content=artifact.content||{};const route=content.reading_route||[];const compare=content.comparison?.rows||[];const model=content.model_draft||{};const claims=content.claims||[];const card=content.reading_card_draft||{};const cardPaper=card.paper_id||'';const newPapers=content.new_papers||[];const changedPapers=content.changed_papers||[];const repeatedPapers=content.repeated_papers||[];return `<section class="agent-artifact"><div class="section-heading"><div><h3>${esc(artifact.title||'研究产物')}</h3><p>${esc(content.overview||'')}</p></div><span class="evaluation-status">${esc(artifact.artifact_type)}</span></div><div class="agent-artifact-metrics"><div><small>候选论文</small><b>${content.coverage?.candidate_count||0}</b></div><div><small>主题分组</small><b>${Object.keys(content.coverage?.topic_groups||{}).length}</b></div><div><small>摘要缺失</small><b>${content.coverage?.missing_abstract||0}</b></div><div><small>全文缺口</small><b>${content.coverage?.missing_fulltext||0}</b></div><div><small>Claim / Evidence</small><b>${claims.length}</b></div></div><div class="agent-artifact-actions">${cardPaper&&card.reading_card?`<button class="button small" data-agent-apply-card="${esc(cardPaper)}">确认写入阅读卡空字段</button>`:''}<button class="button small" data-agent-export-report>导出 Markdown 报告</button></div>${agentPaperOverviewMarkup(content.paper_analysis_overview)}${card.analysis?.prereading_guide?renderPrereadingGuide(card.analysis.prereading_guide):''}${newPapers.length||changedPapers.length||repeatedPapers.length?`<div class="agent-artifact-section"><b>本次追踪变化</b><p>新增 ${newPapers.length} · 元数据/版本变化 ${changedPapers.length} · 重复命中 ${repeatedPapers.length}</p>${[...newPapers.slice(0,6).map(item=>`<span class="agent-uncertainty">新增 · ${esc(item.title||item.paper_key||'')}</span>`),...changedPapers.slice(0,6).map(item=>`<span class="agent-uncertainty">变化 · ${esc(item.title||item.paper_key||'')}</span>`)].join('')}</div>`:''}${model.synthesis?`<div class="agent-synthesis"><b>模型辅助综合 · ${esc(model.model||'')}</b><p>${esc(model.synthesis)}</p><small>引用候选 ${model.cited_candidate_ids?.length||0} 篇 · 未引用结论 ${model.uncited_claim_count||0}</small></div>`:''}${(model.synthesis_evidence||[]).length?`<details class="agent-model-evidence"><summary>综合对应的已保存证据 · ${(model.synthesis_evidence||[]).length}</summary>${(model.synthesis_evidence||[]).slice(0,8).map(ref=>`<div><b>${esc(ref.candidate_id||'')}</b><span>${ref.page!=null?`第 ${esc(ref.page)} 页 · `:''}${esc(ref.section||'来源')} · ${esc(({fulltext_page:'全文页级',abstract_only:'仅摘要',unverified:'未核验'})[ref.scope]||ref.scope||'未核验')}</span><small>${esc(ref.quote||'')}</small></div>`).join('')}</details>`:''}${model.unsupported_theme_count||model.unsupported_gap_count?`<div class="ai-quality-warning">已隐藏缺少候选论文 ID 支持的主题 ${Number(model.unsupported_theme_count||0)} 项、缺口 ${Number(model.unsupported_gap_count||0)} 项。</div>`:''}${model.themes?.length?`<div class="agent-artifact-section"><b>模型归纳主题</b><ul>${model.themes.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:''}${model.gaps?.length?`<div class="agent-artifact-section"><b>待核查的研究缺口</b><ul>${model.gaps.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:''}<div class="agent-artifact-columns"><div><b>阅读路线</b>${route.length?route.slice(0,10).map(item=>`<details class="agent-route-row"><summary><span>${item.order}</span><b>${esc(item.title||'')}</b></summary><div><small>${esc(item.stage||'')} · ${esc(item.reason||'')}</small><p>${esc(item.reading_goal||'')}</p><small>预期产出：${esc(item.expected_output||'')}<br>前置：${esc(item.prerequisites||'')}<br>验证：${(item.verification_questions||[]).map(value=>esc(value)).join('；')}<br>证据：${esc(item.evidence_scope||'unverified')}</small></div></details>`).join(''):'<small>暂无路线信息</small>'}</div><div><b>比较维度</b>${compare.slice(0,12).map(item=>`<details class="agent-compare-row"><summary><b>${esc(item.title||'')}</b><small>${esc([item.year,item.venue,item.relevance,item.evidence_level].filter(Boolean).join(' · '))}</small></summary><div><small>任务边界：${esc(item.applicability_boundary||'未定位')}<br>指标：${esc(item.metric_comparability||'未定位')}<br>复现：${esc(item.reproducibility_signals||'未定位')}<br>证据：${esc((item.evidence_scope||[]).join('、')||'未定位')}</small>${(item.missing_fields||[]).length?`<p class="agent-compare-gap">缺少：${item.missing_fields.map(value=>esc(value)).join('、')}</p>`:''}</div></details>`).join('')||'<small>暂无比较记录</small>'}</div></div>${(content.uncertainties||[]).length?`<div class="agent-uncertainties">${content.uncertainties.map(item=>`<span>${esc(item)}</span>`).join('')}</div>`:''}${content.model_draft_error?`<div class="ai-quality-warning">模型综合暂不可用，已保留本地研究地图：${esc(content.model_draft_error)}</div>`:''}</section>`;}
function autonomousCandidateMarkup(run){
  const records=new Map();
  for(const step of run?.steps||[]){
    const output=step.output||{};
    const papers=[...(Array.isArray(output.papers)?output.papers:[]),...(Array.isArray(output.candidates)?output.candidates:[])];
    for(const paper of papers){if(paper?.id?.startsWith('candidate:')&&!records.has(paper.id))records.set(paper.id,paper);}
  }
  const papers=[...records.values()];
  if(!papers.length)return '<div class="agent-empty-inline">自主 Agent 会根据任务自行选择检索工具；发现的论文会留在候选区，不会自动入库。</div>';
  return `<div class="agent-candidate-toolbar"><span>自主检索候选 ${papers.length} 篇 · 选择后才加入文献库</span><button class="button small primary" data-agent-import>加入选中候选</button></div><div class="agent-candidate-list">${papers.map(p=>`<label class="agent-candidate"><input type="checkbox" data-agent-candidate="${esc(p.id)}"><span class="agent-candidate-main"><b>${esc(p.title||'无标题')}</b><small>${esc([p.year,p.venue,p.relevance_label,p.verification_status==='verified'?'已学术核验':''].filter(Boolean).join(' · '))}</small><span>${esc((p.abstract||'').slice(0,260))}${(p.abstract||'').length>260?'…':''}</span></span><span class="agent-candidate-score">${esc(p.relevance_score??'—')}</span></label>`).join('')}</div>`;
}
function autonomousArtifactMarkup(run){
  const artifact=(run?.artifacts||[]).find(item=>item?.artifact_type==='agent_autonomous_result');
  if(!artifact)return '';
  const content=artifact.content||{};
  return `<section class="agent-artifact agent-autonomous-result"><div class="section-heading"><div><h3>自主 Agent 研究结果</h3><p>${esc(content.objective||run.objective||'')}</p></div><button class="button small" data-agent-export-report>导出 Markdown 报告</button></div><div class="agent-synthesis"><b>基于已执行工具与可追溯结果的综合答复</b><p>${esc(content.answer||'')}</p></div></section>`;
}
const _standardAgentArtifactMarkup=agentArtifactMarkup;
agentArtifactMarkup=function(run){return run?.workflow==='autonomous'?autonomousArtifactMarkup(run):_standardAgentArtifactMarkup(run);};
const _standardAgentCandidateMarkup=agentCandidateMarkup;
agentCandidateMarkup=function(run){return run?.workflow==='autonomous'?autonomousCandidateMarkup(run):_standardAgentCandidateMarkup(run);};
function renderAgentDetail(){
  const goal=agentGoals.find(item=>item.id===activeAgentGoalId), run=activeAgentRun;
  if(!goal)return '<div class="agent-empty-state"><b>先创建一个研究目标</b><span>研究 Agent 会保存目标、执行计划、候选快照和证据状态。</span></div>';
  const status=run?.completion_state||run?.status||goal.status;
  const workflowNames={research_map:'研究地图',evidence_review:'精读与证据核验',follow_up:'前沿追踪',autonomous:'自主 Agent'};
  const selection=goal.scope?.workflow_selection||{};
  const selectionNote=selection.mode==='auto'?`Agent 自动选择了「${workflowNames[goal.workflow]||goal.workflow}」：${selection.reason||''}`:`执行「${workflowNames[goal.workflow]||goal.workflow}」工作流。`;
  const cadenceHours=Number(goal.cadence_hours||168), cadenceText=cadenceHours%24===0?`${cadenceHours/24} 天`:`${cadenceHours} 小时`;
  const scheduleNote=goal.auto_run?`定期追踪已开启 · 每 ${cadenceText} · 下次 ${fmtDate(goal.next_run_at,true)}`:'定期追踪未开启';
  let controls='';
  if(run){
    if(run.status==='awaiting_confirmation')controls='<button class="button primary" data-agent-action="approve">审阅计划并启动</button>';
    if(['queued','running'].includes(run.status))controls+='<button class="button" data-agent-action="pause">暂停</button><button class="button danger" data-agent-action="cancel">取消运行</button>';
    if(['paused','interrupted','failed'].includes(run.status))controls+='<button class="button primary" data-agent-action="resume">继续运行</button><button class="button danger" data-agent-action="cancel">取消运行</button>';
    controls+='<button class="button" data-agent-new-run>新建运行计划</button>';
  }
  if(goal.workflow==='follow_up'&&!['completed','archived'].includes(goal.status))controls+=`<button class="button" data-agent-schedule-toggle>${goal.auto_run?'暂停定期追踪':'开启定期追踪'}</button>`;
  const progress=run?.progress||{}, percent=Number(progress.percent||0), calls=(run?.tool_calls||[]).slice(0,8);
  const completed=(run?.steps||[]).filter(item=>item.status==='success').length, total=(run?.steps||[]).length;
  let html='<section class="agent-detail-head"><div><div class="eyebrow">'+esc(workflowNames[goal.workflow]||goal.workflow)+' · '+esc(AGENT_STATUS_TEXT[status]||status)+'</div><h2>'+esc(goal.name)+'</h2><p>'+esc(goal.objective)+'</p><small class="agent-workflow-note">'+esc(selectionNote)+' · '+esc(scheduleNote)+'</small></div><div class="agent-run-controls">'+controls+'</div></section>';
  if(run){
    const progressLabel=run.workflow==='autonomous'?`自主决策 · ${run.tool_calls?.length||0} 次工具调用`:`${percent}% · ${completed}/${total} 步完成`;
    html+='<section class="surface-card agent-run-panel"><div class="section-heading"><div><h3>执行计划与进度</h3><p>运行 '+esc(run.id.slice(0,8))+(run.error?' · '+esc(run.error):'')+'</p></div><span class="evaluation-status">'+progressLabel+'</span></div>';
    if(run.status==='running')html+='<div class="ai-job-progress"><i style="width:'+Math.min(100,Math.max(0,percent))+'%"></i></div>';
    html+='<div class="agent-step-list">'+agentStepRows(run)+'</div>'+(['success','partial'].includes(run.status)?agentArtifactMarkup(run):'')+'<div class="agent-subsection"><div class="section-heading"><div><h3>候选论文</h3><p>Agent 结果保持候选状态；选中后才会写入长期文献库。</p></div></div>'+agentCandidateMarkup(run)+'</div>';
    if(calls.length)html+='<details class="agent-tool-log"><summary>工具调用记录 · '+run.tool_calls.length+'</summary>'+calls.map(call=>'<div class="source-line"><span><b>'+esc(call.tool_name)+'</b><small>'+esc(call.tool_class)+' · '+esc(call.status)+(call.error?' · '+esc(call.error):'')+'</small></span><span>'+(call.duration_ms?Math.round(call.duration_ms)+' ms':'')+'</span></div>').join('')+'</details>';
    html+='</section>';
  }else html+='<section class="surface-card agent-run-panel"><div class="agent-empty-inline">这个目标还没有运行。创建计划后可以审阅步骤和边界，再启动执行。</div><button class="button primary" data-agent-new-run>生成运行计划</button></section>';
  return html;
}
function renderAgents(){const goalRows=agentGoals.map(goal=>`<button class="agent-goal-row ${goal.id===activeAgentGoalId?'active':''}" data-agent-goal="${goal.id}"><span><b>${esc(goal.name)}</b><small>${esc(goal.objective.slice(0,110))}${goal.objective.length>110?'…':''}${goal.auto_run?' · 定期追踪中':''}</small></span><span class="agent-goal-status">${esc(AGENT_STATUS_TEXT[goal.latest_run?.status||goal.status]||goal.latest_run?.status||goal.status)}</span></button>`).join('');return `${viewHead('RESEARCH AGENT','研究目标','描述任务后由 Agent 选择流程、调用检索与证据工具，并持续记住已发现的论文。',`<button class="button" data-agent-scroll-form>新建目标</button>`)}${agentGoalForm()}<div class="agent-workspace-grid"><aside class="surface-card agent-goal-list"><div class="section-heading"><div><h3>长期研究目标</h3><p>${agentGoals.length} 个目标 · 状态保存在本机数据库</p></div></div>${goalRows||'<div class="agent-empty-inline">目标创建后会长期保存在这里。</div>'}</aside><div class="agent-detail-column">${renderAgentDetail()}</div></div>`;}
async function loadAgentWorkspace(){if(activeView!=='agents'||agentWorkspaceLoading)return;agentWorkspaceLoading=true;clearTimeout(agentWorkspaceTimer);try{const [goalsResult,toolsResult,modelResult]=await Promise.allSettled([api('/api/research-goals'),api('/api/agent-tools'),api('/api/settings/model')]);if(goalsResult.status==='fulfilled')agentGoals=goalsResult.value||[];if(toolsResult.status==='fulfilled')agentTools=toolsResult.value.tools||[];if(modelResult.status==='fulfilled')agentModelConfigured=Boolean(modelResult.value.api_key_set&&modelResult.value.enabled);if(!agentGoals.some(item=>item.id===activeAgentGoalId)){activeAgentGoalId=agentGoals[0]?.id||'';if(activeAgentGoalId)localStorage.setItem('researchdesk.agent-goal',activeAgentGoalId);else localStorage.removeItem('researchdesk.agent-goal');}const selected=agentGoals.find(item=>item.id===activeAgentGoalId);const latestId=selected?.latest_run?.id||'';if(latestId&&activeAgentRun?.id!==latestId){activeAgentRun=await api(`/api/agent-runs/${encodeURIComponent(latestId)}`);}else if(latestId&&activeAgentRun?.id===latestId){activeAgentRun=await api(`/api/agent-runs/${encodeURIComponent(latestId)}`);}else activeAgentRun=null;renderView();}catch(err){if(!agentGoals.length)toast(`研究 Agent 加载失败：${err.message}`,'error');}finally{agentWorkspaceLoading=false;}const run=activeAgentRun;if(run&&['queued','running'].includes(run.status))agentWorkspaceTimer=setTimeout(pollAgentRun,1700);}
