loadAgentWorkspace = async function(){await _loadAgentWorkspace();if(activeView==='agents'&&activeAgentGoalId){const [papersResult,critiquesResult]=await Promise.allSettled([api(`/api/research-goals/${encodeURIComponent(activeAgentGoalId)}/papers`),api(`/api/research-goals/${encodeURIComponent(activeAgentGoalId)}/critiques`)]);agentMemory.papers=papersResult.status==='fulfilled'?(papersResult.value.papers||[]):[];agentMemory.critiques=critiquesResult.status==='fulfilled'?(critiquesResult.value.critiques||[]):[];renderView();}};
async function pollAgentRun(){if(activeView!=='agents'||!activeAgentRun?.id)return;try{activeAgentRun=await api(`/api/agent-runs/${encodeURIComponent(activeAgentRun.id)}`);renderView();if(['queued','running'].includes(activeAgentRun.status)){agentWorkspaceTimer=setTimeout(pollAgentRun,1700);}else if(activeAgentRun.status==='success'||activeAgentRun.status==='failed'||activeAgentRun.status==='partial'||activeAgentRun.status==='awaiting_confirmation'){await loadAgentWorkspace();}}catch{agentWorkspaceTimer=setTimeout(pollAgentRun,3000);}}
async function submitAgentGoal(form){const fields=new FormData(form),value=Object.fromEntries(fields.entries());value.sources=$$("#agent-goal-form input[name='source']:checked").map(input=>input.value);value.auto_run=fields.get('auto_run')==='on';for(const key of ['focus','exclusions','deliverables'])value[key]=String(value[key]||'').split(',').map(item=>item.trim()).filter(Boolean);value.time_range={from:value.year_from||'',to:value.year_to||''};delete value.year_from;delete value.year_to;try{const goal=await api('/api/research-goals',{method:'POST',body:jsonBody(value)});activeAgentGoalId=goal.id;localStorage.setItem('researchdesk.agent-goal',goal.id);const run=await api(`/api/research-goals/${encodeURIComponent(goal.id)}/runs`,{method:'POST',body:jsonBody({trigger:'manual'})});activeAgentRun=run;form.reset();await loadAgentWorkspace();toast('研究计划已生成，正在等待你审阅后启动');}catch(err){toast(`研究目标创建失败：${err.message}`,'error');}}
