 const view=activeView,renderers={home:renderHome,discover:renderDiscover,library:renderLibrary,reading:renderReading,deepread:renderDeepRead,prereading:renderPrereading,automation:renderAutomation,agents:renderAgents,analytics:renderAnalytics,settings:renderSettings};
