// OpenReview is optional because some networks challenge its public API.  It
// is injected after the existing view is rendered so older saved layouts keep
// working and users can opt in without changing their default source set.
function injectOptionalSourceControls(){
  if(activeView!=='discover')return;
  $$('.search-options').forEach(group=>{
    if(group.querySelector('input[name="source"][value="openreview"]'))return;
    const dblp=group.querySelector('input[name="source"][value="dblp"]');
    if(!dblp)return;
    const label=document.createElement('label');label.className='check-label';
    label.innerHTML='<input type="checkbox" name="source" value="openreview"> OpenReview';
    dblp.closest('label')?.after(label);
  });
  const form=$('#discover-form');
  if(form&&!form.querySelector('[data-action="agent-search-plan"]')){
    const button=document.createElement('button');button.type='button';button.className='button';button.dataset.action='agent-search-plan';button.textContent='✦ AI 扩展搜索';
    (form.querySelector('.search-form')||form).append(button);
  }
  const agentButton=form?.querySelector('[data-action="agent-search-plan"]');
  if(agentButton){agentButton.disabled=discoveryStatusActive();agentButton.textContent=discoveryStatusActive()?'✦ AI 搜索中…':'✦ AI 扩展搜索';}
}
function syncDiscoveryFormState(){
  if(activeView!=='discover')return;
  const form=$('#discover-form'), button=form?.querySelector('button[type="submit"]');
  if(!form||!button)return;
  const running=discoveryStatusActive();
  button.disabled=running;
  button.innerHTML=running?`<span class="spinner"></span> ${esc(discoveryProgressText()||'正在检索')}`:'<span>⌕</span> 搜索论文';
  let banner=form.parentElement?.querySelector('.search-run-status');
  const shouldShow=discoveryMeta&&['queued','running','failed','partial','interrupted'].includes(discoveryMeta.status);
  if(!shouldShow){banner?.remove();return;}
  if(!banner){banner=document.createElement('div');banner.className='search-run-status';form.after(banner);}
  banner.className=`search-run-status ${running?'is-running':'is-finished'}`;
  const displayStatus=discoveryDisplayStatus(discoveryMeta);
  const displayProgress=discoveryProgressText({...discoveryMeta,status:displayStatus});
  const savedNotice=displayStatus==='partial'&&discoveryMeta.error?' · 结果已保存，部分持久化步骤异常':'';
  banner.innerHTML=`<b>本次检索 · ${esc(discoveryStatusLabel(displayStatus))}</b><span>${esc(displayProgress)}${savedNotice}${discoveryMeta.error?` · ${esc(discoveryMeta.error)}`:''}</span>`;
}
