const renderWithReadingEvidence=renderView;
renderView=function(){renderWithReadingEvidence();if(activeView==='analytics'&&analytics){$('#app-view')?.insertAdjacentHTML('beforeend',readingEvidencePanel(analytics));}if(activeView==='reading'){injectReaderCard();loadReadingPaperDetail(selectedPaperId);loadReadingPaperAnalysis(selectedPaperId);}updateDiscoverySelectionUi();if(activeView==='settings'&&settingsSnapshot?.model?.endpoint_warning){const card=$('#app-view .settings-grid .settings-card');if(card&&!card.querySelector('.endpoint-warning')){const note=document.createElement('div');note.className='ai-quality-warning endpoint-warning';note.textContent=`配置提醒：${settingsSnapshot.model.endpoint_warning}`;card.insertBefore(note,card.querySelector('.settings-list'));}}};

function injectReaderCard(){const p=papers.find(item=>item.id===selectedPaperId),target=$('.reader-card');if(!p||!target||target.querySelector('.reader-card-section'))return;const detail=readingPaperDetailCache.get(p.id)?.data||{},card=p.reading_card||detail.reading_card||{};const completion=Number(card.completion_pct||0);const section=document.createElement('section');section.className='reader-section reader-card-section';section.id='reading-card-section';section.innerHTML=`<div class="reader-card-heading"><div><h4>结构化阅读卡</h4><p class="reader-card-help">将论文问题、方法、证据、结果、局限和对课题的启发沉淀为可编辑记录。</p></div><span class="reader-card-progress">${completion}%</span></div><div class="reader-card-actions"><span class="ai-hint">可在下方全文分析区让 AI 填充空字段，也可以直接编辑。</span></div><div class="form-grid reading-card-grid">${readingCardFields(card)}</div><div style="display:flex;justify-content:flex-end;margin-top:9px"><button class="button small primary" data-save-reading-card="${p.id}">保存阅读卡</button></div>`;const slot=target.querySelector('.reading-card-slot');if(slot)slot.append(section);else target.append(section);}

function runtimePanel(runtime={}){const pct=value=>`${Number(value||0).toFixed(2)}%`;return `<section class="surface-card runtime-panel"><div class="section-heading" style="margin:0 0 10px"><div><h3>运行时 SLO · 本进程窗口</h3><p>请求量、错误率和延迟用于判断发布后是否需要优化</p></div><span class="evaluation-status">样本 ${runtime.sample_size||0}</span></div><div class="evaluation-grid"><div><small>请求总量</small><b>${runtime.requests_total||0}</b></div><div><small>p50 延迟</small><b>${runtime.p50_ms||0}<small> ms</small></b></div><div><small>p95 延迟</small><b>${runtime.p95_ms||0}<small> ms</small></b></div><div><small>错误率</small><b>${pct(runtime.error_rate_pct)}</b></div></div><div class="evaluation-note">窗口开始于 ${esc(runtime.window_started_at||'进程启动时')} · 服务端错误率 ${pct(runtime.server_error_rate_pct)} · 热点路由 ${runtime.route_count||0} 个</div></section>`;}

function diagnosticsPanel(data={}){const quality=data.data_quality||{}, targets=data.slo_targets||{}, slo=data.slo||{};const connectors=Object.entries(data.connectors||{}).map(([name,item])=>`<span title="${esc(item.role||'')}" class="decision-tag">${esc(SOURCE_NAME[name]||name)} · ${esc(item.access||'')}</span>`).join('');return `<section class="surface-card settings-card diagnostics-panel"><div class="section-heading" style="margin:0 0 10px"><div><h3>发布诊断与数据质量</h3><p>用于日常运维、版本发布、连接器边界和运行时门槛检查</p></div><span class="evaluation-status">${esc(data.release?.app_version||'')}</span></div><div class="settings-list"><div><span>运行环境</span><b>Python ${esc(data.release?.python_version||'')}</b></div><div><span>数据完整度</span><b>摘要缺失 ${quality.missing_abstract_pct||0}% · 强标识缺失 ${quality.missing_strong_identifier_pct||0}%</b></div><div><span>重复风险</span><b>${quality.duplicate_title_year_groups||0} 个同题名/年份组</b></div><div><span>评测覆盖</span><b>${quality.feedback_coverage_pct||0}% · ${quality.judged_matches||0}/${quality.query_matches||0} 已判断</b></div><div><span>SLO 门槛</span><b>p95 ≤ ${targets.p95_ms||0} ms · 5xx ≤ ${targets.server_error_rate_pct||0}% · 当前 ${slo.p95_ms||0} ms / ${slo.server_error_rate_pct||0}%</b></div></div><div class="decision-tags">${connectors}</div></section>`;}

function briefingPanel(data={}){const s=data.summary||{}, topics=(data.topic_breakdown||[]).slice(0,5), next=(data.next_reads||[]).slice(0,3), attention=(data.attention||[]);return `<section class="surface-card" style="margin-top:16px;padding:18px"><div class="section-heading" style="margin:0 0 12px"><div><h3>本周研究简报</h3><p>过去 ${data.window_days||7} 天的新增论文、阅读负载和下一步建议</p></div><button class="text-link" data-nav="analytics">查看数据分析 →</button></div><div class="ops-strip"><div><span>新增论文</span><b>${s.new_papers||0}</b></div><div><span>待读积压</span><b>${s.backlog||0}</b></div><div><span>活跃主题</span><b>${s.active_topics||0}</b></div><div><span>异常同步</span><b>${s.partial_or_failed_runs||0}</b></div></div><div class="settings-grid"><div><small style="color:#95a098;font-size:9px">主题变化</small>${topics.length?topics.map(item=>`<div class="source-line"><span>${esc(item.topic)}</span><b>${item.count}</b></div>`).join(''):'<p style="font-size:10px;color:#a0aaa3">本周还没有新增主题</p>'}</div><div><small style="color:#95a098;font-size:9px">建议下一步</small>${next.length?next.map(item=>`<div class="source-line"><span title="${esc((item.recommendation_reasons||[]).join('；'))}">${esc(item.title)}</span><b>${item.recommendation_score||0}</b></div>`).join(''):'<p style="font-size:10px;color:#a0aaa3">先标记几篇相关论文，研究画像会逐步形成</p>'}</div></div>${attention.length?`<div class="decision-tags" style="margin-top:13px">${attention.map(item=>`<span>! ${esc(item)}</span>`).join('')}</div>`:''}</section>`;}

function renderHome(){
 const read=countStatus('read'), todo=countStatus('to_read')+countStatus('inbox'), reading=countStatus('reading');
 const tracked=queries.filter(q=>q.active).length, recent=appState.recent||[], latest=latestRun();
 const greeting=new Intl.DateTimeFormat('zh-CN',{weekday:'long',month:'long',day:'numeric'}).format(new Date());
 const queue=(papers||[]).filter(p=>['reading','to_read','inbox'].includes(p.status)).sort((a,b)=>({reading:0,to_read:1,inbox:2}[a.status]-({reading:0,to_read:1,inbox:2}[b.status]))).slice(0,5);
 const memoryItems=(recommendations?.recommendations||[]).slice(0,4);
 const memoryMarkup=memoryItems.length?memoryItems.map(item=>`<article class="memory-row"><div class="memory-score">${item.recommendation_score}<small>匹配</small></div><div class="memory-copy"><b data-open-paper="${item.id}">${esc(item.title)}</b><small>${esc((item.recommendation_reasons||[]).slice(0,2).join(' · '))}</small></div><div class="memory-actions"><button class="button small" data-status-paper="${item.id}" data-status="to_read">加入待读</button><button class="plain-icon" title="不再推荐" data-recommendation-feedback="${item.id}" data-decision="irrelevant">×</button></div></article>`).join(''):'<div class="empty-state" style="padding:16px">继续阅读并标记相关性后，这里会逐渐形成个性化推荐。</div>';
 const externalRecommendations=(recommendations?.external_recommendations||[]).slice(0,4);
 const externalMarkup=externalRecommendations.length?`<div class="recommendation-discovery"><div class="section-heading" style="margin:14px 0 8px"><div><h4>外部推荐 · OpenAlex + Semantic Scholar</h4><p>使用成熟学术推荐服务召回，确认后才会保存到文献库</p></div></div>${externalRecommendations.map(item=>`<article class="memory-row external-memory-row"><div class="memory-score">${item.recommendation_score||0}<small>相关</small></div><div class="memory-copy"><a href="${esc(item.url||'')}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a><small>${esc([item.recommendation_provider,item.year,item.venue].filter(Boolean).join(' · '))} · ${esc((item.recommendation_reasons||[])[0]||'官方推荐服务召回')}</small></div><div class="memory-actions"><button class="button small" data-save-recommendation="${esc(item.openalex_id||item.external_id||item.doi||item.arxiv_id||'')}">加入待读</button></div></article>`).join('')}</div>`:'';
 const profileTerms=(recommendations?.profile?.top_terms||[]).slice(0,7).map(term=>`<span class="profile-term">${esc(term)}</span>`).join('');
 const recentMarkup=recent.length?recent.slice(0,4).map(p=>paperRow(p,true)).join(''):emptyState('文献库还没有论文','先搜索一个研究问题，或上传已有 PDF。','<button class="button small" data-nav="discover">发现论文</button>');
 const queueMarkup=queue.length?queue.map(p=>`<button class="home-queue-row" data-open-paper="${esc(p.id)}"><span><b>${esc(p.title)}</b><small>${esc([p.year,STATUS[p.status]].filter(Boolean).join(' · '))}</small></span><span>打开 →</span></button>`).join(''):emptyState('当前没有待读论文','从发现页选择相关候选，或在文献库里标记待读。','<button class="button small" data-nav="discover">发现论文</button>');
 const latestMarkup=latest?`<button class="home-run-row" data-nav="automation"><span class="run-icon ${latest.status==='failed'?'error':''}">${latest.status==='success'?'✓':latest.status==='running'?'↻':'!'}</span><span><b>${esc(latest.query_name||'主题检索')}</b><small>${timeAgo(latest.started_at)} · ${latest.status==='success'?esc(runResultSummary(latest)):esc(latest.error||discoveryStatusLabel(latest.status))}</small></span><span>查看 →</span></button>`:'<div class="home-run-empty">保存研究主题后，可自动追踪新论文。</div>';
 const hasInsights=Boolean(recommendations||briefing);
   const recommendationMethod=recommendations?.recommendation_provider?.message||'根据阅读记录、收藏和相关性反馈排序';
   const insights=hasInsights?`<details class="home-insights"><summary>研究画像与本周简报 <span>展开查看推荐、主题变化和阅读负载</span></summary><div class="home-insights-content">${recommendations?`<section class="memory-panel"><div class="section-heading" style="margin:0 0 9px"><div><h3>下一步建议</h3><p>${esc(recommendationMethod)}</p></div><button class="text-link" data-nav="analytics">查看反馈</button></div>${profileTerms?`<div class="profile-terms">${profileTerms}</div>`:''}<div class="surface-card memory-card">${memoryMarkup}${externalMarkup}</div></section>`:''}${briefing?briefingPanel(briefing):''}</div></details>`:'';
 return `${viewHead('TODAY','今日研究',appState.total?'从待读开始，或继续发现与你课题相关的论文。':'先搜索一个研究问题，或把已有 PDF 放进文献库。',`<button class="button primary" data-nav="discover">搜索论文</button><button class="button" data-action="pdf-import">上传 PDF</button>`)}
 <section class="home-welcome"><div><span>${greeting}</span><h2>${appState.total?'你的研究资料已持续保存':'建立你的第一条研究线索'}</h2><p>${appState.total?`${appState.total} 篇馆藏 · ${tracked} 个追踪主题 · ${todo} 篇待读或待分诊`:'搜索论文后先查看候选，再决定是否加入文献库。PDF、笔记和 AI 分析会保存在本机。'}</p></div><button class="button small" data-action="add-paper">手动添加</button></section>
 <div class="home-summary-strip"><button data-nav="library"><small>文献库</small><b>${appState.total}</b></button><button data-nav="reading"><small>待读 / 新发现</small><b>${todo}</b></button><button data-nav="reading"><small>正在阅读</small><b>${reading}</b></button><button data-nav="automation"><small>追踪主题</small><b>${tracked}</b></button></div>
 <div class="grid home-main-grid"><section><div class="section-heading"><div><h3>继续阅读</h3><p>${queue.length?`${queue.length} 篇排在前面`:'从一篇论文开始'}</p></div><button class="text-link" data-nav="reading">打开阅读台 →</button></div><div class="surface-card home-queue">${queueMarkup}</div></section><aside><div class="section-heading"><div><h3>最近任务</h3><p>自动检索的最新状态</p></div><button class="text-link" data-nav="automation">全部任务 →</button></div><div class="surface-card home-run-list">${latestMarkup}</div></aside></div>
 <section class="home-recent"><div class="section-heading"><div><h3>最近保存的论文</h3><p>搜索结果需经你确认后才会入库</p></div><button class="text-link" data-nav="library">查看文献库 →</button></div><div class="surface-card paper-list">${recentMarkup}</div></section>${insights}`;
}

